print("7b. Detecting QB changes and top teammates who are out...")
role_flags = {}
try:
    _tc = "team" if "team" in stats.columns else "recent_team"
    _wks_done = sorted(int(w) for w in merged["week"].unique())
    # ---- QB per team-week (QB with the most attempts) ----
    _q = stats[stats["position"].astype(str).eq("QB")].copy()
    _q["attempts"] = safe_num(_q["attempts"])
    _q = _q.sort_values("attempts", ascending=False).groupby([_tc, "week"]).head(1)
    _q = _q[_q["attempts"] >= 8]
    _qbw = {(str(r_[_tc]), int(r_["week"])): (r_["player_id"], str(r_.get("player_display_name", r_.get("player_name", "")))) for _, r_ in _q.iterrows()}
    _first = lambda nm: [x_ for x_ in str(nm).split(" ") if x_.lower().strip(".") not in ("jr", "sr", "ii", "iii", "iv")][-1]
    for _t in sorted(set(t_ for t_, _ in _qbw)):
        _seq = [(w_, _qbw[(_t, w_)]) for w_ in _wks_done if (_t, w_) in _qbw]
        if len(_seq) < 3:
            continue
        _lastq = _seq[-1][1][0]
        _streak = 0
        for w_, qq_ in reversed(_seq):
            if qq_[0] == _lastq:
                _streak += 1
            else:
                break
        if _streak < 2 or _streak >= len(_seq):
            continue
        _new = [w_ for w_, qq_ in _seq if qq_[0] == _lastq]
        _old = [w_ for w_, qq_ in _seq if qq_[0] != _lastq]
        _newname = _first(_seq[-1][1][1])
        _oldname = _first([qq_ for w_, qq_ in _seq if qq_[0] != _lastq][-1][1])
        _rows = merged[(merged["team"] == _t) & merged["position"].isin(["WR", "TE"]) & (merged["offense_pct"] >= 0.30)]
        for pid_, d_ in _rows.groupby("player_id"):
            pw_ = set(int(x) for x in d_["week"])
            if (pw_ & set(_old)) and (pw_ & set(_new)) and d_["targets"].sum() >= 8:
                role_flags.setdefault(pid_, []).append({
                    "k": "qb", "tag": "QB change",
                    "txt": f"{_newname} has been the starting QB since Week {min(_new)}. Earlier games were with {_oldname}.",
                    "use": sorted(pw_ & set(_new)), "btn": f"Count only games with {_newname}"})
    # ---- Top WR / RB / TE (when healthy) who is out now -> ranks 2-3 (TE: rank 2) ----
    _thr = {"WR": 0.45, "TE": 0.45, "RB": 0.25}
    _act = merged[merged.apply(lambda r_: r_["offense_pct"] >= _thr.get(r_["position"], 0.45), axis=1)].copy()
    for _t in sorted(_act["team"].dropna().unique()):
        for _pos, _share, _lim in (("WR", "target_share_game", 2), ("RB", "touch_share_game", 2), ("TE", "target_share_game", 1)):
            _d = _act[(_act["team"] == _t) & (_act["position"] == _pos)]
            if _d.empty:
                continue
            _rk = _d.groupby("player_id")[_share].agg(["mean", "count"]).sort_values("mean", ascending=False)
            if len(_rk) < 2:
                continue
            _topv = float(_rk["mean"].iloc[0])
            # "key" players: the leader plus anyone within 10% of his share (a near-tie for WR1 counts as WR1)
            _key = [i_ for i_, v_ in _rk["mean"].items() if v_ >= 0.9 * _topv][:(3 if _pos == "WR" else 2)]
            for _top in _key:
                _ti = inj_by_pid.get(_top)
                if not _ti or _ti["avail"] > 0.3:
                    continue
                _tact = set(int(w_) for w_ in _act[_act["player_id"] == _top]["week"])
                _tname = str(g[g["player_id"] == _top]["player_name"].iloc[0]) if (g["player_id"] == _top).any() else "Top player"
                _tl = [x_ for x_ in _tname.split(" ") if x_.lower().strip(".") not in ("jr", "sr", "ii", "iii", "iv")][-1]
                _rest = [i_ for i_ in _rk.index if i_ != _top][:_lim]
                for pid_ in _rest:
                    d_ = merged[(merged["player_id"] == pid_) & (merged["team"] == _t) & (merged["offense_pct"] >= 0.20)]
                    pw_ = set(int(x) for x in d_["week"])
                    _wo = sorted(pw_ - _tact)
                    if not _wo:
                        continue
                    _with = sorted(pw_ & _tact)
                    role_flags.setdefault(pid_, []).append({
                        "k": "out", "tag": f"{_pos}1 out",
                        "txt": f"{_tname} was a top {_pos} on {_t} when healthy and is {('out' if _ti['avail'] <= 0.1 else 'not expected to play')} now."
                               + (f" He played in W{', W'.join(str(x) for x in _with)}." if _with else ""),
                        "use": _wo, "btn": f"Count only games without {_tl}"})
    print(f"   {sum(len(v) for v in role_flags.values())} flags on {len(role_flags)} players.")
except Exception as e:
    print("   Role flags unavailable:", e)
    role_flags = {}

# ============================================================
# PFR ADVANCED STATS (drops, broken tackles, yards after contact) with league ranks
# ============================================================
ADV = {}
ADV_LG = {}
ADV_BOARD = {"rec": [], "rush": []}
PFR2G = {}
try:
    _pi = player_info.dropna(subset=["pfr_id", "gsis_id"]).drop_duplicates("pfr_id")
    PFR2G = dict(zip(_pi["pfr_id"].astype(str), _pi["gsis_id"].astype(str)))
except Exception as _e:
    print("   PFR id map unavailable:", _e)
try:
    _rec = pd.read_csv(f"{BASE}/pfr_advstats/advstats_week_rec_{SEASON}.csv", low_memory=False)
    _rus = pd.read_csv(f"{BASE}/pfr_advstats/advstats_week_rush_{SEASON}.csv", low_memory=False)
    for _d in (_rec, _rus):
        _d["gsis"] = _d["pfr_player_id"].astype(str).map(PFR2G)
    _recA = _rec.dropna(subset=["gsis"]).groupby("gsis").agg(drops=("receiving_drop", "sum"), bt_rec=("receiving_broken_tackles", "sum")).to_dict("index")
    _rusA = _rus.dropna(subset=["gsis"]).groupby("gsis").agg(car=("carries", "sum"), ybc=("rushing_yards_before_contact", "sum"), yac=("rushing_yards_after_contact", "sum"), bt=("rushing_broken_tackles", "sum"), bt_rec=("receiving_broken_tackles", "sum")).to_dict("index")
    _sx = stats.copy()
    for _c in ("receiving_yards_after_catch", "rushing_fumbles_lost", "receiving_fumbles_lost", "sack_fumbles_lost", "targets", "receptions", "carries"):
        if _c not in _sx.columns:
            _sx[_c] = 0
        _sx[_c] = safe_num(_sx[_c])
    _sx["fum"] = _sx["rushing_fumbles_lost"] + _sx["receiving_fumbles_lost"]
    _sxA = _sx.groupby("player_id").agg(tgt=("targets", "sum"), rec=("receptions", "sum"), yacatch=("receiving_yards_after_catch", "sum"), fum=("fum", "sum"), car=("carries", "sum")).to_dict("index")
    _posmap = dict(zip(g["player_id"], g["position"]))
    _namemap = dict(zip(g["player_id"], g["player_name"]))
    _teammap = dict(zip(g["player_id"], g["team"]))
    _minT, _minC = max(10, 3.5 * max_week), max(15, 6 * max_week)
    _rows = {}
    for _pid, _pos in _posmap.items():
        _x = _sxA.get(_pid)
        if not _x:
            continue
        _r = {"pos": _pos, "tgt": int(_x["tgt"]), "rec": int(_x["rec"]), "fum": int(_x["fum"]), "car": int(_x["car"])}
        _ra, _ru = _recA.get(_pid, {}), _rusA.get(_pid, {})
        _r["drops"] = int(_ra.get("drops", 0) or 0)
        _r["bt_rec"] = int((_ra.get("bt_rec", 0) or 0) if _ra else (_ru.get("bt_rec", 0) or 0))
        if _ru:
            _r["bt_rec"] = max(_r["bt_rec"], int(_ru.get("bt_rec", 0) or 0))
        _r["yacatch"] = float(_x["yacatch"])
        if _ru:
            _r["bt_ru"] = int(_ru.get("bt", 0) or 0)
            _r["ybc"] = float(_ru.get("ybc", 0) or 0)
            _r["yac_ru"] = float(_ru.get("yac", 0) or 0)
            _r["car_pfr"] = int(_ru.get("car", 0) or 0)
        _rows[_pid] = _r
    def _rank(vals, higher_better):
        order = sorted(vals.items(), key=lambda kv: (-kv[1] if higher_better else kv[1]))
        return {k: i + 1 for i, (k, _) in enumerate(order)}
    for _grp in ("WR", "TE", "RB"):
        _ids = [k for k, v in _rows.items() if v["pos"] == _grp]
        # receiving group: WR and TE; rushing group: RB
        _q_rec = [k for k in _ids if _rows[k]["tgt"] >= _minT]
        _q_ru = [k for k in _ids if _grp == "RB" and _rows[k].get("car_pfr", 0) >= _minC]
        _tg = sum(_rows[k]["tgt"] for k in _q_rec)
        _dp = sum(_rows[k]["drops"] for k in _q_rec)
        _lg = (_dp / _tg) if _tg else 0.0
        for k in _ids:
            _rows[k]["xd"] = round(_lg * _rows[k]["tgt"], 1)
        # Raw rates are shown to the reader. Ranks use a volume-adjusted rate: each player's rate is pulled toward the league
        # average in proportion to how little work it is based on (1 target with 0 drops cannot beat 100 targets with 0 drops).
        def _adj(num, den, k, prior):
            return (num + k * prior) / (den + k)
        _lgv = {}
        if _q_rec:
            _sr = sum(_rows[k]["rec"] for k in _q_rec) or 1
            _lgv["dr"] = _lg
            _lgv["btr"] = sum(_rows[k]["bt_rec"] for k in _q_rec) / _sr
            _lgv["yacr"] = sum(_rows[k]["yacatch"] for k in _q_rec) / _sr
        if _q_ru:
            _sc = sum(_rows[k]["car_pfr"] for k in _q_ru) or 1
            _lgv["btc"] = sum(_rows[k]["bt_ru"] for k in _q_ru) / _sc
            _lgv["yacc"] = sum(_rows[k]["yac_ru"] for k in _q_ru) / _sc
            _lgv["ybcc"] = sum(_rows[k]["ybc"] for k in _q_ru) / _sc
        ADV_LG[_grp] = {m: round(v * (100 if m in ("dr", "btr", "btc") else 1), 2) for m, v in _lgv.items()}
        _met = {}
        if _q_rec:
            _met["dr"] = {k: _adj(_rows[k]["drops"], _rows[k]["tgt"], 40, _lgv["dr"]) for k in _q_rec}
            _met["btr"] = {k: _adj(_rows[k]["bt_rec"], max(1, _rows[k]["rec"]), 25, _lgv["btr"]) for k in _q_rec}
            _met["yacr"] = {k: _adj(_rows[k]["yacatch"], max(1, _rows[k]["rec"]), 12, _lgv["yacr"]) for k in _q_rec}
            for k in _q_rec:
                _rows[k]["dr_raw"] = round(100 * _rows[k]["drops"] / _rows[k]["tgt"], 2)
                _rows[k]["btr_raw"] = round(100 * _rows[k]["bt_rec"] / max(1, _rows[k]["rec"]), 2)
                _rows[k]["yacr_raw"] = round(_rows[k]["yacatch"] / max(1, _rows[k]["rec"]), 2)
        if _q_ru:
            _met["btc"] = {k: _adj(_rows[k]["bt_ru"], _rows[k]["car_pfr"], 50, _lgv["btc"]) for k in _q_ru}
            _met["yacc"] = {k: _adj(_rows[k]["yac_ru"], _rows[k]["car_pfr"], 40, _lgv["yacc"]) for k in _q_ru}
            _met["ybcc"] = {k: _adj(_rows[k]["ybc"], _rows[k]["car_pfr"], 40, _lgv["ybcc"]) for k in _q_ru}
            for k in _q_ru:
                _rows[k]["btc_raw"] = round(100 * _rows[k]["bt_ru"] / _rows[k]["car_pfr"], 2)
                _rows[k]["yacc_raw"] = round(_rows[k]["yac_ru"] / _rows[k]["car_pfr"], 2)
                _rows[k]["ybcc_raw"] = round(_rows[k]["ybc"] / _rows[k]["car_pfr"], 2)
        for _m, _v in _met.items():
            _rk = _rank(_v, higher_better=(_m != "dr"))
            for k, val in _v.items():
                _rows[k][_m] = round(val * (100 if _m in ("dr", "btr", "btc") else 1), 2)   # adjusted value
                _rows[k][_m + "_rk"] = _rk[k]
            for k in _ids:
                _rows[k]["n_" + _m] = len(_v)
    for _pid, _r in _rows.items():
        _r["q_rec"] = "dr_rk" in _r
        _r["q_ru"] = "btc_rk" in _r
        if _r["pos"] != "RB" and not _r["q_rec"] and _r["tgt"] < 5:
            continue
        ADV[_pid] = _r
    for _pid, _r in ADV.items():
        _base = [_pid, _namemap.get(_pid, ""), str(_teammap.get(_pid, "")), _r["pos"]]
        if _r.get("q_rec"):
            ADV_BOARD["rec"].append(_base + [_r["tgt"], _r["rec"], _r["drops"], round(_r["dr_raw"], 1), int(_r["bt_rec"]), round(_r["btr_raw"], 1), round(_r["yacr_raw"], 1), round(_r["dr"], 2), round(_r["btr"], 2), round(_r["yacr"], 2)])
        if _r.get("q_ru"):
            ADV_BOARD["rush"].append(_base + [_r["car_pfr"], _r["bt_ru"], round(_r["btc_raw"], 1), round(_r["yacc_raw"], 2), round(_r["ybcc_raw"], 2), _r["drops"], _r["tgt"], round(_r["btc"], 2), round(_r["yacc"], 2), round(_r["ybcc"], 2), round(_r["dr"], 2) if _r.get("q_rec") else None])
    print(f"   PFR advanced stats: {len(ADV)} players ranked ({len(ADV_BOARD['rec'])} receivers, {len(ADV_BOARD['rush'])} backs qualify).")
except Exception as _e:
    print("   PFR advanced stats skipped:", _e)

# ============================================================
# FTN CHARTING: how each team's offense and defense play
# ============================================================
FTN_TEAMS = {}
try:
    _ftn = pd.read_csv(f"{BASE}/ftn_charting/ftn_charting_{SEASON}.csv", low_memory=False)
    _pb = pd.read_csv(f"{BASE}/pbp/play_by_play_{SEASON}.csv.gz", usecols=lambda c: c in ("game_id", "play_id", "posteam", "defteam", "pass", "rush", "season_type", "qb_dropback", "sack"), low_memory=False)
    _pb = _pb[_pb["season_type"] == "REG"] if "season_type" in _pb.columns else _pb
    _ftn["nflverse_game_id"] = _ftn["nflverse_game_id"].astype(str)
    _m = _ftn.merge(_pb, left_on=["nflverse_game_id", "nflverse_play_id"], right_on=["game_id", "play_id"], how="inner")
    for _c in ("is_play_action", "is_screen_pass", "is_motion", "is_no_huddle", "is_rpo"):
        _m[_c] = _m[_c].fillna(False).astype(bool)
    _m["pass"] = safe_num(_m["pass"]); _m["rush"] = safe_num(_m["rush"])
    _m["blitz"] = safe_num(_m["n_blitzers"]).fillna(0) > 0
    _dbk = _m[_m["pass"] == 1]
    for _t, _gg in _m.groupby("posteam"):
        _pp = _gg[_gg["pass"] == 1]
        _pl = _gg[(_gg["pass"] == 1) | (_gg["rush"] == 1)]
        if len(_pl) < 30 or len(_pp) < 15:
            continue
        FTN_TEAMS[str(_t)] = {"pl": int(len(_pl)),
            "pa": round(100 * _pp["is_play_action"].mean(), 1), "sc": round(100 * _pp["is_screen_pass"].mean(), 1),
            "mo": round(100 * _pl["is_motion"].mean(), 1), "nh": round(100 * _pl["is_no_huddle"].mean(), 1),
            "rpo": round(100 * _pl["is_rpo"].mean(), 1), "bl": round(100 * _pp["blitz"].mean(), 1),
            "pr": round(100 * len(_pp) / len(_pl), 1)}
    _db = _dbk.groupby("defteam")["blitz"].mean()
    for _t, v in _db.items():
        if str(_t) in FTN_TEAMS:
            FTN_TEAMS[str(_t)]["dbl"] = round(100 * float(v), 1)
    print(f"   FTN play style: {len(FTN_TEAMS)} teams.")
except Exception as _e:
    print("   FTN play style skipped:", _e)

