#profile .hero2 .rankline i{font-style:normal;font-weight:700;background:#eef2f8;color:#33445f;padding:4px 8px;border-radius:999px;white-space:nowrap}
#profile .hero2 .scorebig{font-size:40px!important}
#profile .hero2 .scorelab{font-size:10px!important;margin-top:4px!important;letter-spacing:.12em!important}
#profile .hero2 .scoresub{font-size:11px!important;margin-top:1px!important}
