 #profile .hero2 .portrait img{width:308px!important;height:308px!important}
 #profile .hero2 .hid{text-align:left!important;align-self:end}
 #profile .hero2 .hid,#profile .hero2 .hid>*{text-align:left!important;justify-self:start!important}
  #profile .hero2 .hid h1{font-size:64px!important;letter-spacing:-2.5px!important;line-height:1!important}
 #profile .hero2 .hid .meta{font-size:22px!important;margin-top:10px}
 #profile .hero2 .hid .rankline{font-size:17px!important;justify-content:flex-start!important;margin-top:14px;gap:10px}
 #profile .hero2 .hid .rankline i{padding:9px 16px!important;font-size:16px!important}
 #profile .hero2 .hs.left,#profile .hero2 .hs.right{text-align:left!important}
 #profile .hero2 .hs .scorebig{font-size:112px!important;line-height:.95!important}
 #profile .hero2 .hs .scorelab{font-size:21px!important;margin-top:12px!important}
 #profile .hero2 .hs .scoresub{font-size:16px!important}
 #profile .hero2 .hpjW,#profile .hero2 .hol{justify-self:start!important;text-align:left!important}
 #profile .hero2 .heroPj{font-size:22px!important}
 #profile .hero2 .heroPj b{font-size:28px!important}
 #profile .hero2 .hol{display:flex;flex-wrap:wrap;gap:14px;align-items:center}
 #profile .hero2 .outlook{margin-left:0!important;font-size:19px!important;padding:12px 24px!important}
 #profile .bdgBtn{width:62px!important;height:68px!important}
